head.script:
scwin.btn_pop_onclick = function (e) {
    $p.openPopup("/jira/fail/RELEASE_202611/fail_contextMenu_wframePopup_hiddenBehindPopup_popup.xml", {
        id : "pop_cm", type : "wframePopup", popupName : "wframePopup", modal : false,
        width : "400px", height : "250px", left : "460px", top : "140px"
    });
};

// 메뉴 첫 항목(Alpha) 위치에 메뉴가 맨 위로 그려져 눈에 보이는지 확인
scwin.checkVisible = function (cm, title) {
    setTimeout(function () {
        let visible = false;
        let layer = document.getElementById(cm.id + "_portal");
        let panel = layer ? layer.firstElementChild : null;
        let first = panel ? panel.firstElementChild : null;
        if (first) {
            let r = first.getBoundingClientRect();
            let top = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);
            visible = first.contains(top);
        }
        scwin.setReturnValue(title + " → isOpen()=" + cm.isOpen() + ", 첫 항목(Alpha) 보임=" + visible);
    }, 100);
};

// 리턴 값 초기화
scwin.btn_clear_onclick = function (e) {
    tbx_return.setValue("");
};

// 리턴 값 설정
scwin.setReturnValue = function (strValue) {
    tbx_return.setValue(tbx_return.getValue() + strValue);
    tbx_return.setValue(tbx_return.getValue() + "\n");
};
